def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def need_verb(tt):
    s = text(tt)
    if 'clean' in s:
        return 'clean'
    if 'heat' in s:
        return 'heat'
    if 'cool' in s:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = getv(ctx, 'task.task_type', '')
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = need_verb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['transformed'] = False
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    old = nb.get('placed_count', 0)
    try:
        old = int(old)
    except Exception:
        old = 0
    if pc > old:
        nb['placed_count'] = pc
    locs = getv(ctx, 'world.placed_locations', [])
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and target and target not in inv and 'not carrying' not in inv and 'nothing' not in inv)
    need = 2 if 'two' in text(tt) else 1
    placed = nb.get('placed_count', 0)
    try:
        placed = int(placed)
    except Exception:
        placed = 0
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        placed = placed + 1
    if placed >= need:
        stage = 'done'
    elif wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        else:
            stage = 'put_target'
    else:
        if placed > 0 and placed < need:
            stage = 'find_target'
        else:
            stage = 'take_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    return None

