def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('transform_verb') or ''
    tt = nb.get('task_type') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the target type; do not place it at the destination. Recover by setting it aside only if needed, then find the target.'
    elif stage == 'transform' and verb:
        msg = 'You are carrying the target; use the admissible ' + verb + ' action before putting it at the ' + dest + '.'
    elif stage == 'put_target':
        msg = 'You are carrying the target; go to the ' + dest + ' and use the admissible put action there. Do not put it on other receptacles.'
    elif stage == 'take_target':
        msg = 'Search unopened or unvisited containers for the ' + target + '; do not place non-target objects at the destination.'
    elif stage == 'find_target' and 'two' in str(tt).lower():
        msg = 'One target is already placed; leave it there, find another ' + target + ', and use the same ' + dest + ' if possible.'
    if not msg:
        return None
    key = stage + ':' + msg
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

