def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    verb = nb.get('transform_verb') or need_verb(tt)
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act:
        return None
    carrying = bool(target and target in text(getv(ctx, 'world.inventory', '')))
    placed = nb.get('placed_count', 0)
    try:
        placed = int(placed)
    except Exception:
        placed = 0
    locs = nb.get('placed_locations') or []
    if isinstance(locs, (list, tuple, set)):
        locs = [text(x) for x in locs]
    else:
        locs = [text(locs)]
    if target and act.startswith('take ') and target in act and locs and placed > 0:
        for loc in locs:
            if loc and loc in act:
                return {'kind': 'block_and_prompt', 'message': 'Do not take back a target that is already placed. Leave it there and continue with the remaining subgoal.'}
    if target and dest and act.startswith('put ') and target in act and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Keep the target and navigate to the correct destination.'}
    if target and dest and act.startswith('put ') and target in act and dest in act and verb and not nb.get('transformed'):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet; first use the required ' + verb + ' action while carrying it.'}
    return None
